const resp = $input.first().json;
const items = resp?.data?.list || [];
if (items.length === 0) {
  return [{ json: { error: 'No data', items: [] } }];
}
const item = items[0];
const brief = item.brief || '';
const lines = brief.split('\n').filter(l => l.trim());
const newsItems = [];
for (const line of lines) {
  const num = line.match(/^[0-9]+[.]\s*(.+)/);
  if (num) newsItems.push(num[1].trim());
}
return [{ json: {
  title: item.title || '',
  date: (item.time || '').split(' ')[0] || new Date().toISOString().slice(0, 10),
  newsItems,
  videoUrl: item.url || ''
}}];

const data = $input.first().json;
if (!data.newsItems || data.newsItems.length === 0) {
  return [{ json: { error: data.error || 'No news' } }];
}
let summary = '';
data.newsItems.forEach((item, i) => { summary += (i+1) + '. ' + item + '\n'; });
const markdown = '## \ud83d\udcfa ' + data.title + '\n\n**\u65e5\u671f\uff1a** ' + data.date + '\n\n### \ud83d\udccb \u4eca\u65e5\u8981\u95fb\n\n' + summary + '\n\n[\u25b6\ufe0f \u89c2\u770b\u5b8c\u6574\u89c6\u9891](' + data.videoUrl + ')';
const payload = {
  msg_type: 'interactive',
  card: {
    schema: '2.0',
    config: { wide_screen_mode: true },
    header: {
      title: { tag: 'plain_text', content: '\u65b0\u95fb\u8054\u64ad ' + data.date },
      template: 'red'
    },
    body: { elements: [{ tag: 'markdown', content: markdown }] }
  }
};
return [{ json: { payload, webhookUrl: $env.N8N_01_FEISHU_WEBHOOK } }];
